// Generated by scripts/gen-explainers.mjs from app/components/frame/frame.explainer.html. Do not edit.
const html = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\"\n      content=\"initial-scale=1, width=device-width\">\n<title>The frame</title>\n<style>\n  /* Two palettes, picked by the reader's system setting. */\n  :root {\n    color-scheme: light dark;\n    --page-bg: #fbfaf7;\n    --page-text: #1d1d1b;\n    --muted: #5b5b57;\n    --rule: #d9d6cf;\n    --diagram-line: #55534e;\n    --diagram-text: #1d1d1b;\n    --diagram-edge-text: #45433f;\n    --node-component-fill: #e8f0fb;\n    --node-component-stroke: #4a72b0;\n    --node-store-fill: #eaf5ec;\n    --node-store-stroke: #4a8a5a;\n    --node-external-fill: #f6eee2;\n    --node-external-stroke: #a27a3c;\n    --node-person-fill: #f3e9f5;\n    --node-person-stroke: #8a5a96;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root {\n      --page-bg: #17181a;\n      --page-text: #e8e6e1;\n      --muted: #a9a6a0;\n      --rule: #3a3b3e;\n      --diagram-line: #b9b6af;\n      --diagram-text: #ecebe7;\n      --diagram-edge-text: #cfccc5;\n      --node-component-fill: #1d2a3d;\n      --node-component-stroke: #7fa3dc;\n      --node-store-fill: #1d3024;\n      --node-store-stroke: #79b98a;\n      --node-external-fill: #33291b;\n      --node-external-stroke: #d1a462;\n      --node-person-fill: #2e2233;\n      --node-person-stroke: #bb8cc7;\n    }\n  }\n  html, body {\n    margin: 0;\n    background: var(--page-bg);\n    color: var(--page-text);\n  }\n  body {\n    padding: 2rem 3rem;\n    font-size: 18px;\n    line-height: 1.6;\n    font-family: \"Source Serif 4\",\n      \"Iowan Old Style\", Georgia,\n      \"Times New Roman\", serif;\n  }\n  @media (max-width: 640px) {\n    body { padding: 1rem; font-size: 16px; }\n  }\n  h1, h2, h3, svg text {\n    font-family: \"Inter\", \"Segoe UI\",\n      system-ui, -apple-system,\n      Helvetica, Arial, sans-serif;\n  }\n  h1 {\n    font-size: 2rem;\n    margin: 0 0 1rem;\n  }\n  h2 {\n    font-size: 1.4rem;\n    margin: 2.5rem 0 0.75rem;\n    padding-bottom: 0.3rem;\n    border-bottom: 1px solid var(--rule);\n  }\n  p, li { margin: 0 0 1rem; }\n  code {\n    font-size: 0.9em;\n    font-family: \"JetBrains Mono\",\n      \"Cascadia Code\", Consolas,\n      \"Liberation Mono\", monospace;\n  }\n  table { width: 100%; border-collapse: collapse; margin: 0 0 1rem; }\n  th, td {\n    border: 1px solid var(--rule);\n    padding: 0.4rem 0.7rem;\n    text-align: left;\n    vertical-align: top;\n  }\n  .table-wrap { overflow-x: auto; }\n  #diagram {\n    display: block;\n    width: 100%;\n    height: auto;\n    margin: 1rem 0 2rem;\n  }\n</style>\n</head>\n<body>\n<h1>The frame</h1>\n<p>The frame is the layout a tom.Quest page renders inside when its row in <code>app/components/page-routes.ts</code> carries <code>frame: true</code>. It is being designed as the one layout every page of the site will share. For now one page uses it: <code>/frame</code>, a page only Tom can open, which holds every component that the <code>/jarvis</code> and <code>/agents</code> pages render, the real components reading the real data, so that the layout is judged against real content. <code>/jarvis</code>, <code>/agents</code> and every other page keep their own layout until the frame is settled. This page explains what the frame puts on the screen, how its drawers open, move and share the room, and why it is built the way it is. It describes the code in <code>app/components/frame/</code>, the directory this file sits in, and the page in <code>app/frame/</code>.</p>\n\n<h2>What the screen is made of</h2>\n<p>Across the top of the screen runs the site header, a bar 40 pixels high and as wide as the screen. It holds, from the left, the site's symbol (pressing it goes to the home page), the page's name followed by its (i) button, and, at the right end, a field to navigate to another page, the account button (it reads \"Log in\" for a visitor and shows the username once signed in) and, for Tom only, a dot showing the state of the connection to the database. The header is not a drawer and has no handle: it never moves, and nothing ever covers it.</p>\n<p>Everything below the header is the stage. The stage holds a center and up to four drawers, one for each edge of the screen: top, left, right and bottom. The center is the area in the middle where the page shows its main content. A drawer is a panel that is pulled out from its edge. Each drawer is made of two parts, its content and its handle. The handle is a strip 28 pixels thick along the drawer's inner edge, the edge that faces the center. While a drawer is shut, only its handle shows, lying against the edge of the stage. While it is open, its content fills the space between the edge of the stage and the handle, and the handle sits on the content's inner side and moves with it. The picture below shows the screen with all four drawers open; the side drawers are drawn narrow so that every label fits.</p>\n<svg id=\"diagram\"></svg>\n<p>All four handles are the same component: the same thickness, the same look and the same behaviour, differing only in which edge they belong to. The center is inset from the stage's edges by one handle's thickness on every edge that has a drawer, so that a shut drawer's handle never covers it. On a screen 1440 pixels wide and 900 pixels high the center therefore starts 28 pixels from the left and 68 pixels from the top (40 for the header and 28 for the top handle), and it is 1384 pixels wide and 804 pixels high. Nothing a drawer does changes that box: the center never moves and never changes size, and an open drawer lies over the part of the center next to its edge.</p>\n\n<h2>How the drawers share the stage</h2>\n<p>Drawers never lie over each other. The stage is shared out in a fixed order. The left and right drawers come first: each runs the full height of the stage, from just below the header to the bottom of the screen. The top and bottom drawers come second: each runs only between the inner edges of the two side drawers, handles included. The top drawer sits directly below the header and the bottom drawer against the bottom of the screen. When a side drawer opens, shuts or is dragged, the top and bottom drawers, their handles with them, grow or shrink at the same moment so that their ends stay against the side drawers, and whatever they hold is laid out again in the narrower or wider space, scrolling inside the drawer if it no longer fits. No part of any drawer is hidden behind another.</p>\n<p>Two drawers on opposite edges, left and right or top and bottom, share one axis. Together they may take the length of that axis less three handle thicknesses: their own two handles and one more, so that the handles of the drawers between them always keep some length. On a screen 1440 pixels wide the two side drawers may be 1356 pixels wide together; on a screen 900 pixels high the top and bottom drawers may be 776 pixels high together, since the header takes 40. When both drawers of a pair are open and want more than that, one of them has the room first: the drawer being dragged, or, when none is, the one opened last. The other gives way, shrinking down to its smallest size; once it is at its smallest size, the first stops growing. Dragging a side drawer into the other side drawer therefore pushes the other back to its smallest size and then halts, and letting go of it, or dragging back, lets the other return to the size it had. The same holds for the top and bottom drawers.</p>\n<p>On a narrow screen two opposite drawers may not fit even at their smallest sizes. A phone 390 pixels wide has 306 pixels to share between the side drawers, and each needs at least 160. There, opening one side drawer shuts the other, and a drawer dragged out past half its smallest size shuts the other at once.</p>\n\n<h2>What each drawer holds</h2>\n<p>Each edge has one role on every page, so the same edge means the same kind of content wherever it is opened. The frame itself knows nothing about what a drawer holds; the roles are a rule for pages, and every drawer opens, moves and shuts the same way whatever it holds.</p>\n<div class=\"table-wrap\">\n<table>\n  <tr><th>Part</th><th>Role</th><th>What it holds on <code>/frame</code></th><th>Size it first opens at on <code>/frame</code></th></tr>\n  <tr><td>Center</td><td>The whole: everything the page covers, at once.</td><td>The map of the system's components and the timeline of every agent run, for the chosen window of time.</td><td>Fixed; see above.</td></tr>\n  <tr><td>Top drawer</td><td>Scope: what the page covers.</td><td>The controls that choose the window of time and filter the timeline, then the week calendar with its repeating todos.</td><td>360 pixels high.</td></tr>\n  <tr><td>Left drawer</td><td>The index: every list.</td><td>The todo lists of <code>/jarvis</code> (messages to sign, todos awaiting a ruling, rulings being applied, every todo with its search and filters) and the list of agents of <code>/agents</code>, side by side once the drawer is wide enough for both, one above the other before that.</td><td>420 pixels wide.</td></tr>\n  <tr><td>Right drawer</td><td>One thing whole.</td><td>The thing last pressed anywhere on the page: a todo with its verdict buttons, time notes and facts; a code todo; an agent with its conversation, message box and model choice; or the definition of a vocabulary word. Its handle reads that thing's name.</td><td>480 pixels wide.</td></tr>\n  <tr><td>Bottom drawer</td><td>The raw record.</td><td>The rulings and the changes recorded in the chosen window; for Tom, a column of diagnostics beside them.</td><td>280 pixels high.</td></tr>\n</table>\n</div>\n<p>A page sets, for each drawer, its handle's label, its content, and optionally the size it first opens at and the smallest and largest size it may be dragged to. Without them a drawer first opens at 320 pixels and may be dragged between 160 pixels and 85% of its axis, and never past what the axis leaves for it, as described above. A page may also leave an edge out; that edge then has no handle, and the center reaches the stage's edge there.</p>\n<p>The diagnostics column in the bottom drawer shows the current route, the signed-in role, the state of the connection to Convex, the screen size, the last console warnings and errors the page captured, and a button that copies all of it as text. The dot at the right end of the header opens the bottom drawer to it.</p>\n\n<h2>What a handle shows</h2>\n<p>A handle shows its drawer's label and, after it, its signals, and it may hold buttons. A signal is one typed value the page computes from the same data its drawer shows, so the handle and the drawer cannot disagree. A page cannot put anything else on a handle.</p>\n<div class=\"table-wrap\">\n<table>\n  <tr><th>Kind</th><th>What it shows</th><th>On <code>/frame</code></th></tr>\n  <tr><td>count</td><td>A number in a monospaced font, in the colour the page gives it.</td><td>On the left handle, the number of todos awaiting a ruling; on the bottom handle, the number of rulings in the window.</td></tr>\n  <tr><td>dot</td><td>A small coloured circle for a state.</td><td>Not used yet.</td></tr>\n  <tr><td>age</td><td>The time since a moment, in one short unit such as 40s, 12m, 3h or 5d, which turns yellow past a limit the page sets.</td><td>Not used yet.</td></tr>\n</table>\n</div>\n<p>The colours are green, yellow, red, orange and grey, the site's existing ones, which the code names ok, warn, error, accent and faint. When a drawer is shut and its signals differ from what they were when it was last shut, its handle shows a short orange mark before the label, so a change shows without opening the drawer. An open drawer's handle has an orange edge. On the top and bottom handles the label reads across; on the side handles it runs along the handle, the left one reading from bottom to top and the right one from top to bottom. A label too long for its handle ends in an ellipsis.</p>\n\n<h2>Pulling a drawer out and putting it away</h2>\n<p>The whole handle is the control. Press it anywhere along its length and its drawer opens to the size it was last left at, or to the page's first size the first time. Press the handle of an open drawer, which now sits near the center, and the drawer shuts. Press and drag the handle instead and the drawer follows the pointer: the handle stays under the pointer for as long as the button or finger is down, and the drawer stops at its largest size or where it meets the room the opposite drawer keeps. A movement of fewer than 4 pixels counts as a press rather than a drag. Let go of a drawer dragged to less than half its smallest size and it shuts; let go of it between that and its smallest size and it settles at its smallest size; let go anywhere else and it stays at that size. Pulled out less than its smallest size, a drawer keeps its content at the smallest width and slides it into view rather than squeezing it.</p>\n<p>A button on a handle only does its own thing: pressing it never opens, shuts or drags the drawer. Opening and shutting take 150 milliseconds, and are instant when the reader's system asks for reduced motion; during a drag the drawer moves with the pointer and nothing animates. The same drag works with a finger on a phone, and because it starts on the handle, which lies inside the page, it does not compete with the phone's own swipes from the very edge of the screen.</p>\n<p>Which drawers are open, the size each was last left at, which side drawer and which of the top and bottom drawers was opened last, and what each shut drawer's signals were are remembered per page in the browser's local storage through a Zustand store (<code>frame-store.ts</code>), so a page reopens as it was left. None of it is written into the page's address.</p>\n\n<h2>How a move is drawn</h2>\n<p>Where each drawer lies is computed in code, not left to the page's styles. <code>rules.ts</code> holds the rules as plain functions: <code>sharePair</code> decides how far each of two opposite drawers is pulled out, and <code>drawerBox</code> turns that into the drawer's position and size. <code>frame.tsx</code> writes the result straight onto each drawer element, on every pointer movement of a drag and on every frame of an opening or a shutting, so no part of the page is re-rendered while a drawer moves.</p>\n<p>One more step keeps a move smooth when a drawer holds a long list. The todo lists on <code>/frame</code> hold more than a thousand rows, and laying them out again at a new width takes tens of milliseconds, longer than the 16.7 milliseconds one frame of a 60-frames-per-second display allows. So while any drawer is moving, the width each drawer's content is laid out at changes only in steps of 40 pixels, always rounded toward narrower, while the drawer's edge and handle follow the pointer exactly. Content therefore never runs past its drawer, and between steps nothing inside a drawer is laid out or drawn again. The moment the movement ends, every drawer's content fills its drawer exactly. For the same reason, the rows of the todo lists on <code>/frame</code> that are scrolled out of view are skipped when the lists are laid out.</p>\n<p>No drawer carries a CSS transform, a z-index or containment. Each of those would make a drawer the reference box for any dialog opened inside it, and a dialog meant to cover the whole screen, such as the one that asks for a ruling's sentence, would instead be held inside the drawer. The header carries a z-index of 40 so that its navigate list lies over the drawers; dialogs have 50 and an explainer 60. These values are the <code>--z-*</code> entries at the top of <code>app/globals.css</code>.</p>\n\n<h2>Keys</h2>\n<p>The keys work whenever the keyboard is not typing into a text field and no dialog is open.</p>\n<div class=\"table-wrap\">\n<table>\n  <tr><th>Key</th><th>Effect</th></tr>\n  <tr><td>W, A, S, D</td><td>Open or shut the top, left, bottom and right drawer.</td></tr>\n  <tr><td>Shift with W, A, S or D</td><td>Open that drawer and move keyboard focus into it.</td></tr>\n  <tr><td>/</td><td>Move keyboard focus to the navigate field in the header.</td></tr>\n  <tr><td>Escape</td><td>Close an open explainer first, then an open dialog, then the open drawers one at a time: the top, the side drawer opened last, the other side drawer, the bottom.</td></tr>\n</table>\n</div>\n<p>Each handle's label is also a button the Tab key reaches, and Enter or Space on it opens or shuts the drawer.</p>\n\n<h2>The (i) button and explainers</h2>\n<p>An (i) button sits right after the name of the thing it explains, one per component. Pressing it opens that component's explainer over the whole screen, under a strip holding the explainer's title and a × button; the × or the Escape key closes it. An explainer is one self-contained HTML file committed beside the code it describes and named <code>&lt;name&gt;.explainer.html</code>; this page is <code>frame.explainer.html</code>, opened from the (i) after the page's name in the header.</p>\n<p>The explainer is shown in an iframe, a page embedded in the page, with two protections. The iframe is sandboxed with scripts allowed but without an origin of its own, so the script that draws its diagram cannot read the site's storage, cookies or page, and cannot navigate the site, submit a form or open a window. And the viewer inserts a Content-Security-Policy tag at the start of the explainer's head that refuses every network request. An explainer carries a light and a dark palette and picks one by the reader's system setting, which inside an iframe is the operating system's setting, not the site's; the site is always dark, so the viewer rewrites the file's palette choice so that the dark palette always applies. The same file opened from disk still follows the system setting.</p>\n<p>The (i) names its explainer by a typed argument: <code>scripts/gen-explainers.mjs</code> finds every <code>*.explainer.html</code> under <code>app/</code> and writes <code>explainer-registry.generated.ts</code>, whose type <code>ExplainerId</code> lists exactly the names that have a file, so naming a missing explainer fails the type check. Each file becomes its own module, loaded only when its (i) is pressed. <code>explainers.test.ts</code> fails when the committed registry differs from what the script would write.</p>\n\n<h2>What the frame leaves unchanged</h2>\n<p>For a page marked <code>frame: true</code>, <code>app/components/app-shell.tsx</code> renders no navigation bar and no top padding, and does not draw the diagnostics panel that elsewhere slides in from the left and pushes the page aside, since pushing the center is what the frame rules out; the diagnostics are in the bottom drawer instead. Every other page is unchanged. <code>/jarvis</code> and <code>/agents</code> look and behave as before; three of their files gained an addition that <code>/frame</code> uses and they do not: <code>app/agents/window/window-view.tsx</code> exports the window view's state and controls as parts, <code>definition-drawer.tsx</code> beside it exports a word's definition without its fixed side panel, and <code>app/jarvis/components/everything-tab.tsx</code> takes an optional handler that shows a pressed row elsewhere instead of opening it in place. Inside the frame all text is set in IBM Plex Sans, with IBM Plex Mono for numbers, identifiers and code.</p>\n\n<script>\n// The diagram is two lists; change them and reload, nothing else.\n// A node: id, label (lines; the first is its name), x, y, w, h in\n// diagram units, and kind: component, store, external or person.\n// An edge: from and to (node ids) and a label (\"\" for none).\nconst NODES = [\n  { id: \"header\", x: 20, y: 20, w: 900, h: 52, kind: \"person\",\n    label: [\"Site header\", \"home · page name (i) · navigate · account · diagnostics\"] },\n  { id: \"left-drawer\", x: 20, y: 84, w: 150, h: 516, kind: \"component\",\n    label: [\"Left drawer\", \"the index\"] },\n  { id: \"left-handle\", x: 178, y: 84, w: 70, h: 516, kind: \"external\",\n    label: [\"Left\", \"handle\"] },\n  { id: \"top-drawer\", x: 256, y: 84, w: 428, h: 84, kind: \"component\",\n    label: [\"Top drawer\", \"scope · runs between the side drawers\"] },\n  { id: \"top-handle\", x: 256, y: 176, w: 428, h: 44, kind: \"external\",\n    label: [\"Top handle\"] },\n  { id: \"center\", x: 256, y: 228, w: 428, h: 172, kind: \"store\",\n    label: [\"Center\", \"the whole · never moves\", \"drawers lie over its edges\"] },\n  { id: \"bottom-handle\", x: 256, y: 408, w: 428, h: 44, kind: \"external\",\n    label: [\"Bottom handle\"] },\n  { id: \"bottom-drawer\", x: 256, y: 460, w: 428, h: 140, kind: \"component\",\n    label: [\"Bottom drawer\", \"the raw record · runs between the side drawers\"] },\n  { id: \"right-handle\", x: 692, y: 84, w: 70, h: 516, kind: \"external\",\n    label: [\"Right\", \"handle\"] },\n  { id: \"right-drawer\", x: 770, y: 84, w: 150, h: 516, kind: \"component\",\n    label: [\"Right drawer\", \"one thing whole\"] },\n];\nconst EDGES = [];\n\n(() => {\n  const SVG_NS = \"http://www.w3.org/2000/svg\";\n  const svg = document.querySelector(\"#diagram\");\n  const R = 8;          // corner radius of a box\n  const HEAD = 11;      // arrowhead length\n  const HALF = 5.5;     // arrowhead half width\n  const STEP = 18;      // label line height\n  const byId = new Map(NODES.map((n) => [n.id, n]));\n  const W = Math.max(...NODES.map((n) => n.x + n.w)) + 20;\n  const H = Math.max(...NODES.map((n) => n.y + n.h)) + 20;\n  svg.setAttribute(\"viewBox\", \"0 0 \" + W + \" \" + H);\n  svg.setAttribute(\"role\", \"img\");\n  svg.style.maxWidth = W + \"px\"; // shrink to fit, never grow past 1:1\n\n  const el = (tag, attrs, style = {}) => {\n    const e = document.createElementNS(SVG_NS, tag);\n    Object.entries(attrs).forEach(([k, v]) => e.setAttribute(k, v));\n    Object.assign(e.style, style);\n    svg.appendChild(e);\n    return e;\n  };\n  const mid = (n) => [n.x + 0.5 * n.w, n.y + 0.5 * n.h];\n\n  // Where the ray from n's middle toward (tx, ty) leaves its rounded box.\n  const border = (n, tx, ty) => {\n    const [cx, cy] = mid(n);\n    const dx = tx - cx, dy = ty - cy;\n    const hw = n.w / 2, hh = n.h / 2;\n    // Dividing by a zero delta gives Infinity, so no special case is needed.\n    const k = Math.min(hw / Math.abs(dx),\n      hh / Math.abs(dy));\n    const px = cx + dx * k, py = cy + dy * k;\n    const onSide = Math.abs(px - cx) <= hw - R || Math.abs(py - cy) <= hh - R;\n    if (onSide) return [px, py];\n    // In a corner: meet the corner's circle instead of the square corner.\n    const qx = cx - (cx + Math.sign(dx) * (hw - R));\n    const qy = cy - (cy + Math.sign(dy) * (hh - R));\n    const a = dx * dx + dy * dy;\n    const b = 2 * (qx * dx + qy * dy);\n    const c = qx * qx + qy * qy - R * R;\n    const root = Math.sqrt(b * b - 4 * a * c);\n    const s = (root - b) / (2 * a);\n    return [cx + dx * s, cy + dy * s];\n  };\n\n  // Arrows before boxes, so no arrow crosses a box's text.\n  for (const { from, to, label } of EDGES) {\n    const f = byId.get(from), t = byId.get(to);\n    const [x1, y1] = border(f, ...mid(t));\n    const [x2, y2] = border(t, ...mid(f));\n    const ang = Math.atan2(y2 - y1, x2 - x1);\n    const ux = Math.cos(ang), uy = Math.sin(ang);\n    const bx = x2 - HEAD * ux, by = y2 - HEAD * uy;\n    const LINE = \"var(--diagram-line)\";\n    el(\"line\", { x1, y1, x2: bx, y2: by },\n      { stroke: LINE, strokeWidth: \"1.6\" });\n    const tip = [[x2, y2], [bx + HALF * uy, by - HALF * ux],\n      [bx - HALF * uy, by + HALF * ux]];\n    el(\"polygon\", { points: tip.map((p) => p.join(\",\")).join(\" \") },\n      { fill: LINE });\n    if (!label) continue;\n    // The label sits beside the line on its upper side, growing away from it.\n    let nx = -uy, ny = ux;\n    const flip = ny > 0 || (ny === 0 && nx > 0);\n    if (flip) { nx *= -1; ny *= -1; }\n    let anchor = \"start\";\n    if (Math.abs(nx) < 0.3) anchor = \"middle\";\n    else if (nx < 0) anchor = \"end\";\n    el(\"text\", {\n      x: (x1 + x2) / 2 + nx * 10,\n      y: (y1 + y2) / 2 + ny * 10,\n      \"text-anchor\": anchor,\n      \"dominant-baseline\":\n        ny < -0.9 ? \"auto\" : \"middle\",\n    }, {\n      fill: \"var(--diagram-edge-text)\",\n      fontSize: \"13px\",\n      paintOrder: \"stroke\",\n      stroke: \"var(--page-bg)\",\n      strokeWidth: \"5px\",\n      strokeLinejoin: \"round\",\n    }).textContent = label;\n  }\n\n  // Boxes, then their labels: the name larger and bold, the rest plain.\n  for (const n of NODES) {\n    const box = { width: n.w, height: n.h, x: n.x, y: n.y };\n    el(\"rect\", { ...box, rx: R, ry: R }, {\n      fill: \"var(--node-\" + n.kind + \"-fill)\",\n      stroke: \"var(--node-\" + n.kind + \"-stroke)\",\n      strokeWidth: \"1.4\",\n    });\n    const [cx, cy] = mid(n);\n    const first = cy - ((n.label.length - 1) * STEP) / 2;\n    n.label.forEach((text, i) => {\n      el(\"text\", {\n        x: cx, y: first + i * STEP,\n        \"text-anchor\": \"middle\",\n        \"dominant-baseline\": \"middle\",\n      }, {\n        fill: \"var(--diagram-text)\",\n        fontSize: i === 0 ? \"15px\" : \"13px\",\n        fontWeight: i === 0 ? \"600\" : \"400\",\n      }).textContent = text;\n    });\n  }\n})();\n</script>\n</body>\n</html>\n";
export default html;
